var now = DateTimeOffset.Now;

var chat = new ArcChatView
{
    Width = 680,
    Height = 470,
    ShowComposer = true,
    Placeholder = "Message the team",
};

chat.AddMessage(new PuraChatMessage
{
    Role = PuraChatRole.User,
    Markdown = "Can you add the new screenshots?",
    CreatedAt = now.AddMinutes(-9),
});
chat.AddMessage(new PuraChatMessage
{
    Role = PuraChatRole.Assistant,
    ToolCalls = new[]
    {
        new PuraToolCall
        {
            Id = "call-1",
            Name = "repo.write",
            Status = PuraToolCallStatus.Succeeded,
            Arguments = "{ \"path\": \"release-notes.md\" }",
            Result = "written · 18,432 bytes",
        },
    },
    Markdown = "Release notes saved next to the pricing screenshot.",
});

// 流式：上游 PuraStreamingSession 负责增量与全量校正
var streaming = new PuraChatMessage { Id = "m2", Role = PuraChatRole.Assistant };
var session = chat.BeginStreamingMessage(streaming);
session.Append("### Changelog\n\n- screenshot added");
await session.CompleteAsync();

chat.Send += (_, draft) => SendMessage(draft.Text, draft.Attachments);
